// ?removeAllCoverage@CellAndObjectIntersection@@ present-unmatched
void CellAndObjectIntersection::removeAllCoverage()
{
	if (m_module == NULL)
	{
		DEBUG_CRASH(("COI not in use"));
		return;
	}

	m_cell->friend_removeFromCellList(this);
	m_cell = NULL;
	m_module = NULL;
}

